    """Remove all registered jobs."""
    _jobs.clear()


def disable_job(name):
    """Disable a job without removing it."""
    job = _jobs.get(name)
    if job:
        job.enabled = False


def enable_job(name):
    """Enable a previously disabled job."""
    job = _jobs.get(name)
    if job:
        job.enabled = True

